import{_ as s,c as i,af as n,o as t}from"./chunks/framework.BOn264RY.js";const u=JSON.parse('{"title":"CLI configuration","description":"Configure network proxies and environment variables used by the Ts.ED CLI binaries.","frontmatter":{"title":"CLI configuration","description":"Configure network proxies and environment variables used by the Ts.ED CLI binaries.","head":[["link",{"rel":"canonical","href":"https://tsed.dev/introduction/configuration.html"}]]},"headers":[],"relativePath":"introduction/configuration.md","filePath":"introduction/configuration.md","lastUpdated":1788515248000}'),a={name:"introduction/configuration.md"};function o(r,e,p,d,c,l){return t(),i("div",null,[...e[0]||(e[0]=[n(`<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /introduction/configuration.md for this page in Markdown format</div><h1 id="cli-configuration" tabindex="-1">CLI configuration <a class="header-anchor" href="#cli-configuration" aria-label="Permalink to &quot;CLI configuration&quot;">​</a></h1><p>Most teams can run <code>tsed</code> and <code>tsed-mcp</code> with zero setup, but locked-down networks sometimes need explicit proxy values. The CLI reuses npm&#39;s config files and environment variables, so anything that works for npm also works here.</p><h2 id="proxy-settings-via-npm-config" tabindex="-1">Proxy settings via npm config <a class="header-anchor" href="#proxy-settings-via-npm-config" aria-label="Permalink to &quot;Proxy settings via npm config&quot;">​</a></h2><p>Set the proxy values once and every CLI command—project generation, MCP server bootstrap, package installs—will respect them:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> proxy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://username:password@host:port</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https-proxy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://username:password@host:port</span></span></code></pre></div><p>These commands update your global <code>~/.npmrc</code>. You can edit that file directly if you prefer:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>proxy=http://username:password@host:port</span></span>
<span class="line"><span>https-proxy=http://username:password@host:port</span></span>
<span class="line"><span>https_proxy=http://username:password@host:port</span></span></code></pre></div><h2 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment variables&quot;">​</a></h2><p>When scripting inside CI pipelines (where editing <code>.npmrc</code> is inconvenient), export the standard variables before invoking the CLI:</p><ul><li><code>HTTPS_PROXY</code> / <code>HTTP_PROXY</code>: primary proxy URLs.</li><li><code>NO_PROXY</code>: comma-separated hostnames to bypass the proxy (useful for <code>localhost</code> or internal registries).</li><li><code>NODE_TLS_REJECT_UNAUTHORIZED=0</code>: opt-out of TLS verification for self-signed certs. Use only in trusted environments.</li></ul><p>Because the CLI spins up HTTP clients for prompts, tasks, and MCP transports, make sure whichever method you choose (npm config or env vars) is in place before running <code>tsed ...</code> or <code>tsed-mcp</code>.</p>`,12)])])}const m=s(a,[["render",o]]);export{u as __pageData,m as default};
